context.pre:
@font-face {
    font-family: "Example Serif";
    src: url("example-serif.woff2") format("woff2");
    font-weight: 400 700;
    font-style: normal;
}

chapter {
    font-family: "Example Serif", serif;
}

stepxmp.pre:
@font-face {
    font-family: "Example Serif";
    src: local("Example Serif Regular"),
         url("example-serif.woff2") format("woff2"),
         url("example-serif.otf") format("opentype");
}

@font-face {
    font-family: "Example Sans";
    src: url("example-sans-variable.woff2");
    font-weight: 300 800;
    font-width: 75% 125%;
    font-style: oblique 0deg 12deg;
}

@font-face {
    font-family: "Document";
    src: url("latin.woff2");
    unicode-range: U+0000-024F;
}

@font-face {
    font-family: "Document";
    src: url("cyrillic.woff2");
    unicode-range: U+0400-04FF;
}

@font-face {
    font-family: "Example Sans";
    src: url("example-sans.woff2");
    size-adjust: 105%;
    ascent-override: 90%;
    descent-override: 22%;
    line-gap-override: 0%;
}
